      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font-family: Arial, Helvetica, sans-serif;
      background:
        radial-gradient(circle at top, rgba(14, 165, 233, 0.14), transparent 35%),
        linear-gradient(180deg, #020617 0%, #0f172a 100%);
      color: var(--text);
    }

    .support-card {
      width: min(100%, 520px);
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: 20px;
      background: var(--panel);
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    h1 {
      margin: 0 0 10px;
      font-size: 1.95rem;
      line-height: 1.1;
    }

    .intro {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-size: 0.95rem;
      font-weight: 700;
    }

    input {
      width: 100%;
      padding: 14px 16px;
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: 12px;
      background: var(--input-bg);
      color: var(--text);
      font-size: 1rem;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #64748b;
    }

    input:focus {
      border-color: rgba(56, 189, 248, 0.75);
      box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.16);
      transform: translateY(-1px);
    }

    .helper-text,
    .error-message,
    .success-message {
      font-size: 0.88rem;
      line-height: 1.4;
    }

    .helper-text {
      color: var(--muted);
    }

    .error-message {
      color: var(--error);
      min-height: 1.2em;
    }

    .form-field.has-error input {
      border-color: rgba(251, 113, 133, 0.85);
      box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
    }

    button {
      margin-top: 6px;
      border: 0;
      border-radius: 12px;
      padding: 14px 18px;
      font-size: 1rem;
      font-weight: 700;
      color: #082032;
      background: linear-gradient(135deg, var(--accent) 0%, #7dd3fc 100%);
      cursor: pointer;
      transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      box-shadow: 0 18px 30px rgba(14, 165, 233, 0.25);
    }

    button:hover {
      filter: brightness(1.03);
      transform: translateY(-1px);
    }

    button:active {
      transform: translateY(0);
    }

    .success-message {
      margin: 4px 0 0;
      color: #86efac;
      min-height: 1.2em;
    }
  </style>
</head>
<body>
  <section class="support-card" aria-labelledby="support-heading">
    <h1 id="support-heading">Contact Support</h1>
    <p class="intro">Share your details and our team will follow up as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" placeholder="Jordan Lee" required>
        <div class="error-message" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="email">Email address</label>
        <input id="email" name="email" type="email" autocomplete="email" placeholder="jordan@example.com" required>
        <div class="error-message" aria-live="polite"></div>
      </div>

      <div class="form-field">
        <label for="phone">Phone number</label>
        <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="+1 555-123-4567">
        <div class="helper-text">Expected format: +1 555-123-4567 or (555) 123-4567.</div>
        <div class="error-message" aria-live="polite"></div>
      </div>

      <button type="submit">Submit</button>
      <p class="success-message" id="form-status" aria-live="polite"></p>
    </form>
  </section>

  <script>
    const form = document.getElementById("support-form");
    const statusMessage = document.getElementById("form-status");
    const fields = Array.from(form.querySelectorAll("input"));
    const validators = {
      fullName(value) {
        if (!value.trim()) {
          return "Full name is required.";
        }

        if (value.trim().length < 2) {
          return "Enter your full name.";
        }

        return "";
      },
      email(value) {
        if (!value.trim()) {
          return "Email address is required.";
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(value.trim())) {
          return "Enter a valid email address.";
        }

        return "";
      },
      phone(value) {
        if (!value.trim()) {
          return "";
        }

        const phonePattern = /^\+?[\d\s().-]{7,20}$/;
        if (!phonePattern.test(value.trim())) {
          return "Enter a valid phone number using the expected format.";
        }

        return "";
      }
    };

    function setFieldError(input, message) {
      const field = input.closest(".form-field");
      const errorElement = field.querySelector(".error-message");
      const hasError = Boolean(message);

      field.classList.toggle("has-error", hasError);
      input.setAttribute("aria-invalid", String(hasError));
      errorElement.textContent = message;
    }

    function validateField(input) {
      const validationKey = input.name;
      const message = validators[validationKey](input.value);
      setFieldError(input, message);
      return !message;
    }

    fields.forEach((input) => {
      input.addEventListener("blur", () => {
        validateField(input);
      });

      input.addEventListener("input", () => {
        if (input.closest(".form-field").classList.contains("has-error")) {
          validateField(input);
        }

        if (statusMessage.textContent) {
          statusMessage.textContent = "";
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const isValid = fields.map(validateField).every(Boolean);
      if (!isValid) {
        statusMessage.textContent = "";
        return;
      }

      statusMessage.textContent = "Your message details are ready to send.";
      form.reset();
      fields.forEach((input) => setFieldError(input, ""));
    });
  </script>
</body>
</html>
